package main

import "sync"

// historySummaryChunkStore is an append-only bounded representation for large history payloads.
// It keeps summaries separate from point chunks so readers do not rebuild full route payloads.
type historySummaryChunkStore struct {
	mu sync.Mutex
	summaries map[string]historySummaryRecord
	chunks map[string][]historyPointChunk
}

type historySummaryRecord struct {
	UserID string
	VehicleID int
	SessionID string
	PointCount int
	ChunkCount int
}

type historyPointChunk struct {
	Sequence int
	Points []historyRoutePointRecord
}

type historyRoutePointRecord struct {
	Latitude float64
	Longitude float64
}

func newHistorySummaryChunkStore() *historySummaryChunkStore {
	return &historySummaryChunkStore{summaries: make(map[string]historySummaryRecord), chunks: make(map[string][]historyPointChunk)}
}

func (s *historySummaryChunkStore) putSummary(key string, record historySummaryRecord) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.summaries[key] = record
}

func (s *historySummaryChunkStore) appendChunk(key string, chunk historyPointChunk) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.chunks[key] = append(s.chunks[key], chunk)
}

